sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_safeRender;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_count;
uniform float amzp_direction;
uniform float amzp_spread;
uniform float amzp_strandLength;
uniform float amzp_lengthVar;
uniform float amzp_thickness;
uniform float amzp_thickVar;
uniform float amzp_taper;
uniform float amzp_rootFade;
uniform float amzp_progress;
uniform float amzp_source;
uniform float amzp_sourceSize;
uniform float amzp_bend;
uniform float amzp_curl;
uniform float amzp_frequency;
uniform float amzp_evolution;
uniform float amzp_evolveSpeed;
layout(color) uniform half4 amzp_colorStart;
layout(color) uniform half4 amzp_colorEnd;
uniform float amzp_glow;
uniform float amzp_brightVar;
uniform float amzp_seed;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        if (int(amzp_blendMode) == 4) return b + f * (1.0 - b.a);
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float h1(float x, float k) { return fract(sin(x * 91.345 + k * 47.13 + amzp_seed * 13.7) * 43758.5453); }
    float segDist(float2 p, float2 a, float2 b, out float t) {
        float2 ab = b - a;
        t = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-6), 0.0, 1.0);
        return length(p - a - ab * t);
    }
    void nmMain() {
        float2 W = layer;
        float U = min(W.x, W.y);
        float zm = max(amzp_scale * 2.0, 0.002);
        float2 p = (amzLayerNorm() - 0.5) * W - float2(amzp_position.x, -amzp_position.y) * (screen.zw.x / max(screen.zw.x, 1.0));
        p = nmRot(p, radians(amzp_angle)) / (zm * max(amzp_stretch, float2(0.01)));
        float AAz = 0.6 / zm;
        float evo = amzp_evolution + time * amzp_evolveSpeed;
        float n = clamp(floor(amzp_count + 0.5), 1.0, 48.0);
        float pr = clamp(amzp_progress, 0.0, 1.0);
        float3 acc = float3(0.0);
        float accA = 0.0;
        for (int i = 0; i < 48; i++) {
            float fi = float(i);
            if (fi >= n) break;
            float r1 = h1(fi, 1.0), r2 = h1(fi, 2.0), r3 = h1(fi, 3.0), r4 = h1(fi, 4.0), r5 = h1(fi, 5.0), r6 = h1(fi, 6.0);
            float a = radians(amzp_direction + (r2 - 0.5) * amzp_spread);
            float2 d = float2(sin(a), cos(a));
            float2 nn = float2(-d.y, d.x);
            float ss = amzp_sourceSize * U;
            float2 o = float2(0.0);
            float ad = radians(amzp_direction);
            float2 dd = float2(sin(ad), cos(ad));
            if (int(amzp_source) == 1) o = float2(-dd.y, dd.x) * (r1 - 0.5) * ss;
            else if (int(amzp_source) == 2) { float ca = r1 * 6.2831853; o = float2(cos(ca), sin(ca)) * ss * 0.5; }
            float len = max(amzp_strandLength * U * (1.0 - amzp_lengthVar * r3), 1.0);
            float th = max(amzp_thickness * (1.0 - amzp_thickVar * r4), 0.2);
            float amp = amzp_bend * len * 0.3;
            float ampC = amzp_curl * len * 0.09;
            float2 mid = o + d * len * 0.5;
            if (length(p - mid) > len * 0.5 + amp + ampC * 2.0 + th * 8.0 + 4.0) continue;
            float ph = r5 * 6.2831853, ph2 = r6 * 6.2831853;
            float best = 1e6, bt = 0.0;
            float2 prev = o;
            float fq = amzp_frequency * (0.75 + 0.5 * r1);
            for (int j = 1; j <= 32; j++) {
                float t = float(j) / 32.0 * pr;
                float w = sin(t * fq * 2.2 + ph + evo) * 0.65 + sin(t * fq * 4.3 + ph2 - evo * 1.3) * 0.35;
                float wc = sin(t * fq * 5.0 + ph2 * 1.7 + evo * 1.7);
                float wc2 = cos(t * fq * 5.0 + ph2 * 1.7 + evo * 1.7);
                float gr = t * t * (3.0 - 2.0 * t);
                float2 cur = o + d * (t * len + ampC * gr * wc2) + nn * (amp * t * w + ampC * gr * wc);
                float st;
                float dist = segDist(p, prev, cur, st);
                if (dist < best) { best = dist; bt = (float(j - 1) + st) / 32.0 * pr; }
                prev = cur;
            }
            if (pr <= 0.0) continue;
            float rf = clamp(amzp_rootFade, 0.0, 1.0);
            float root = rf > 0.001 ? smoothstep(0.0, rf, bt) : 1.0;
            float wdt = th * (1.0 - amzp_taper * bt / max(pr, 1e-3) * 0.9) * (0.35 + 0.65 * root) * 0.5;
            float core = 1.0 - smoothstep(wdt - AAz, wdt + AAz, best);
            float halo = amzp_glow * exp(-best / max(wdt * 5.0, 0.5)) * 0.35;
            float k = clamp(core + halo, 0.0, 1.0) * (1.0 - clamp(amzp_brightVar, 0.0, 1.0) * r3 * 0.8) * (0.02 + 0.98 * root * root);
            float3 col = mix(amzp_colorStart.rgb, amzp_colorEnd.rgb, bt);
            acc = acc + col * k * (1.0 - accA * 0.5);
            accA = clamp(accA + k * (1.0 - accA), 0.0, 1.0);
        }
        float A = clamp(accA, 0.0, 1.0);
        float4 strands = float4(min(acc, float3(A)), A);
        float4 base = inside(amzLayerNorm()) ? amzTexture(0, amzScreenNorm()) : float4(0.0);
        amzOutput = nmBlend(base, nmGradMap(strands));
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
